  const headings = groups.map((c) => [headingOf(c)?.textContent, headingOf(c)?.getAttribute('title')]);
  const groupRows = groups.flatMap((c) => [...c.querySelectorAll('tbody tr')].map((tr) => cells(tr).slice(0, 2).join(' | ')));
