    const [model] = (await api.listCatalog()).map((c) => c.id);
    const page = await mount(`/requests?models=${encodeURIComponent(model ?? '')}`, { now: CLOCK_ORIGIN });
    chipOf(page, 'model')?.querySelector('.chip__body')?.click();
