    '/keys': ['search: Search keys', 'Add filter', 'Create key', 'edge: Refresh, count'],
    '/pools': ['Create pool', 'edge: Refresh, count'],
    '/quota': ['Refresh all', 'edge: Refresh, count'],
    '/sessions': ['Columns', 'edge: Refresh, count'],
